CREATE EXTENSION IF NOT EXISTS pg_trgm;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='personal_space_maintenance') THEN CREATE ROLE personal_space_maintenance NOLOGIN; END IF; END $$;
ALTER TABLE admin_users ADD CONSTRAINT admin_singleton CHECK(singleton_key=1 AND session_version>0 AND (NOT mfa_enabled OR totp_secret_encrypted IS NOT NULL));
ALTER TABLE contents ADD CONSTRAINT content_states CHECK(type IN ('ARTICLE','MOMENT','ALBUM') AND module IN ('LIFE','KNOWLEDGE') AND (type='ARTICLE' OR module='LIFE') AND state_version>0 AND effective_visibility IN ('PUBLIC','PRIVATE') AND (deleted_at IS NULL OR effective_visibility='PRIVATE') AND ((publication_state='NEVER_PUBLISHED' AND published_revision_id IS NULL AND first_published_at IS NULL AND last_published_at IS NULL AND effective_visibility='PRIVATE') OR (publication_state IN ('PUBLISHED','UNPUBLISHED') AND published_revision_id IS NOT NULL AND first_published_at IS NOT NULL AND last_published_at IS NOT NULL AND first_published_at<=last_published_at AND (publication_state='PUBLISHED' OR effective_visibility='PRIVATE'))));
ALTER TABLE content_revisions ADD CONSTRAINT revision_numbers CHECK(version_number>0 AND ((revision_kind='PUBLISHED' AND published_edition_number>0) OR (revision_kind='MANUAL_SNAPSHOT' AND published_edition_number IS NULL)));
ALTER TABLE content_drafts ADD CONSTRAINT draft_number CHECK(revision_number>0 AND payload_schema_version=1);
ALTER TABLE content_revisions ADD CONSTRAINT revision_schema CHECK(snapshot_schema_version=1);
CREATE FUNCTION ps_payload_valid(p jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT COALESCE(jsonb_typeof(p)='object' AND p->'schemaVersion'='1'::jsonb AND jsonb_typeof(p->'placements')='array' AND jsonb_typeof(p->'tagIds')='array' AND jsonb_typeof(p->'taxonomySnapshot')='object' AND p->>'type' IN ('ARTICLE','MOMENT','ALBUM') AND p->>'module' IN ('LIFE','KNOWLEDGE') AND jsonb_typeof(p->'title')='string' AND jsonb_typeof(p->'bodyMarkdown')='string',false) $$;
ALTER TABLE content_drafts ADD CONSTRAINT draft_payload_shape CHECK(ps_payload_valid(draft_payload));
ALTER TABLE content_revisions ADD CONSTRAINT revision_payload_shape CHECK(ps_payload_valid(snapshot));
CREATE UNIQUE INDEX categories_root_slug_unique ON categories(module,slug) WHERE parent_id IS NULL;
CREATE UNIQUE INDEX categories_root_name_unique ON categories(module,normalized_name) WHERE parent_id IS NULL;
ALTER TABLE categories ADD CONSTRAINT category_values CHECK(module IN ('LIFE','KNOWLEDGE') AND sort_order>=0 AND length(btrim(name)) BETWEEN 1 AND 100 AND length(btrim(normalized_name))>0 AND slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND parent_id IS DISTINCT FROM id);
ALTER TABLE tags ADD CONSTRAINT tag_values CHECK(length(btrim(name)) BETWEEN 1 AND 100 AND length(btrim(normalized_name))>0 AND slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
CREATE UNIQUE INDEX content_one_canonical ON content_routes(content_id) WHERE route_kind='CANONICAL';
ALTER TABLE content_routes ADD CONSTRAINT route_values CHECK(path ~ '^/(life|knowledge)/[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$' AND ((route_kind='TOMBSTONE' AND content_id IS NULL) OR (route_kind IN ('CANONICAL','ALIAS') AND content_id IS NOT NULL)));
ALTER TABLE media ADD CONSTRAINT media_values CHECK(storage_provider='S3' AND mime_type IN ('image/jpeg','image/png','image/webp') AND size_bytes>0 AND checksum_sha256 ~ '^[a-f0-9]{64}$' AND ((width IS NULL AND height IS NULL) OR (width>0 AND height>0)) AND processing_status IN ('UPLOADING','PROCESSING','READY','FAILED') AND (NOT capture_time_trusted OR captured_at IS NOT NULL));
CREATE UNIQUE INDEX media_one_active_variant ON media_variants(media_id,variant_type) WHERE is_active;
ALTER TABLE media_variants ADD CONSTRAINT variant_values CHECK(variant_type IN ('THUMBNAIL','DISPLAY') AND processing_version>0 AND size_bytes>0 AND width>0 AND height>0 AND mime_type='image/webp' AND (NOT is_active OR metadata_sanitized));
ALTER TABLE idempotency_records ADD CONSTRAINT idempotency_values CHECK(status IN ('PROCESSING','COMPLETED','FAILED') AND request_hash ~ '^[a-f0-9]{64}$' AND expires_at>created_at AND (status<>'COMPLETED' OR (response_status BETWEEN 200 AND 599 AND response_reference IS NOT NULL)));
ALTER TABLE operation_jobs ADD CONSTRAINT job_values CHECK(job_type IN ('MEDIA_PROCESS','MEDIA_GC','EXPORT','BACKUP') AND attempts>=0 AND jsonb_typeof(payload)='object' AND status IN ('PENDING','RUNNING','VERIFYING','SUCCEEDED','FAILED') AND ((status IN ('RUNNING','VERIFYING') AND lease_until IS NOT NULL AND lease_token IS NOT NULL) OR (status NOT IN ('RUNNING','VERIFYING') AND lease_until IS NULL AND lease_token IS NULL)) AND (status NOT IN ('SUCCEEDED','FAILED') OR completed_at IS NOT NULL));
ALTER TABLE outbox_events ADD CONSTRAINT outbox_values CHECK(attempts>=0 AND status IN ('PENDING','RUNNING','PROCESSED','FAILED') AND ((status='RUNNING' AND lease_until IS NOT NULL AND lease_token IS NOT NULL) OR (status<>'RUNNING' AND lease_until IS NULL AND lease_token IS NULL)) AND (status<>'PROCESSED' OR processed_at IS NOT NULL));
ALTER TABLE security_challenges ADD CONSTRAINT challenge_values CHECK(token_hash ~ '^[a-f0-9]{64}$' AND session_hash ~ '^[a-f0-9]{64}$' AND session_version>0 AND expires_at>created_at AND purpose IN ('REAUTH','MFA_BINDING','RECOVERY_LOGIN') AND operation IN ('PASSWORD_CHANGE','MFA_REPLACE','RECOVERY_RESET','SESSIONS_REVOKE','EXPORT_CREATE','BACKUP_CREATE') AND (purpose='REAUTH' OR operation='MFA_REPLACE') AND ((purpose='MFA_BINDING' AND used_at IS NULL AND encrypted_payload IS NOT NULL) OR ((purpose<>'MFA_BINDING' OR used_at IS NOT NULL) AND encrypted_payload IS NULL)));
ALTER TABLE backup_runs ADD CONSTRAINT backup_values CHECK(backup_type IN ('DAILY','WEEKLY','MONTHLY','YEARLY','MANUAL') AND status IN ('PENDING','RUNNING','VERIFYING','SUCCEEDED','FAILED') AND local_status IN ('PENDING','RUNNING','SUCCEEDED','FAILED') AND integrity_status IN ('PENDING','RUNNING','SUCCEEDED','FAILED') AND offsite_status IN ('PENDING','RUNNING','SUCCEEDED','FAILED') AND (size_bytes IS NULL OR size_bytes>0) AND (checksum IS NULL OR checksum ~ '^[a-f0-9]{64}$') AND (status<>'SUCCEEDED' OR (local_status='SUCCEEDED' AND integrity_status='SUCCEEDED' AND offsite_status='SUCCEEDED' AND completed_at IS NOT NULL AND verified_at IS NOT NULL AND manifest_path IS NOT NULL)));
ALTER TABLE backup_copies ADD CONSTRAINT copy_values CHECK(copy_type IN ('LOCAL','OFFSITE') AND status IN ('PENDING','RUNNING','SUCCEEDED','FAILED') AND (checksum IS NULL OR checksum ~ '^[a-f0-9]{64}$') AND (status<>'SUCCEEDED' OR (verified_at IS NOT NULL AND checksum IS NOT NULL)));
ALTER TABLE restore_drills ADD CONSTRAINT drill_values CHECK(status IN ('RUNNING','PASSED','FAILED') AND jsonb_typeof(verification_summary)='object' AND (status='RUNNING' OR completed_at IS NOT NULL));
ALTER TABLE system_settings ADD CONSTRAINT settings_object CHECK(jsonb_typeof(setting_value)='object' AND (setting_key<>'site.profile' OR (setting_value ?& ARRAY['siteTitle','siteIntro'] AND jsonb_typeof(setting_value->'siteTitle')='string' AND length(btrim(setting_value->>'siteTitle')) BETWEEN 1 AND 100 AND jsonb_typeof(setting_value->'siteIntro')='string' AND length(setting_value->>'siteIntro')<=500 AND (setting_value - 'siteTitle' - 'siteIntro')='{}'::jsonb)));
CREATE INDEX search_title_trgm ON content_search_documents USING gin(title gin_trgm_ops);
CREATE INDEX search_summary_trgm ON content_search_documents USING gin(summary gin_trgm_ops);
CREATE INDEX search_body_trgm ON content_search_documents USING gin(searchable_text gin_trgm_ops);
CREATE INDEX search_category_trgm ON content_search_documents USING gin(category_text gin_trgm_ops);
CREATE INDEX search_tags_trgm ON content_search_documents USING gin(tags_text gin_trgm_ops);
ALTER TABLE contents ALTER CONSTRAINT contents_id_published_revision_id_fkey DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE content_publications ALTER CONSTRAINT content_publications_content_id_revision_id_fkey DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE content_search_documents ALTER CONSTRAINT content_search_documents_content_id_revision_id_fkey DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION ps_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT pg_has_role(current_user,'personal_space_maintenance','MEMBER') THEN RAISE EXCEPTION 'immutable history or audit' USING ERRCODE='23514'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER immutable_revision BEFORE UPDATE OR DELETE ON content_revisions FOR EACH ROW EXECUTE FUNCTION ps_immutable();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION ps_immutable();
CREATE FUNCTION ps_taxonomy_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p categories%ROWTYPE; BEGIN
 IF TG_TABLE_NAME='categories' THEN
  IF TG_OP='UPDATE' AND OLD.is_system AND NOT pg_has_role(current_user,'personal_space_maintenance','MEMBER') THEN RAISE EXCEPTION 'system category is protected' USING ERRCODE='23514'; END IF;
  IF NEW.parent_id IS NOT NULL THEN SELECT * INTO p FROM categories WHERE id=NEW.parent_id FOR UPDATE; IF NOT FOUND OR p.parent_id IS NOT NULL OR p.module<>NEW.module OR p.deleted_at IS NOT NULL OR EXISTS(SELECT 1 FROM categories WHERE parent_id=NEW.id) THEN RAISE EXCEPTION 'category depth/module invalid' USING ERRCODE='23514'; END IF; END IF;
  IF TG_OP='UPDATE' AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL AND (EXISTS(SELECT 1 FROM draft_categories WHERE category_id=NEW.id) OR EXISTS(SELECT 1 FROM revision_categories WHERE category_id=NEW.id) OR EXISTS(SELECT 1 FROM content_publications WHERE category_id=NEW.id) OR EXISTS(SELECT 1 FROM categories WHERE parent_id=NEW.id AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'category remains referenced' USING ERRCODE='23514'; END IF;
 ELSE
  IF TG_OP='UPDATE' AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL AND (EXISTS(SELECT 1 FROM draft_tags WHERE tag_id=NEW.id) OR EXISTS(SELECT 1 FROM revision_tags WHERE tag_id=NEW.id) OR EXISTS(SELECT 1 FROM content_tags WHERE tag_id=NEW.id)) THEN RAISE EXCEPTION 'tag remains referenced' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER category_guard BEFORE INSERT OR UPDATE ON categories FOR EACH ROW EXECUTE FUNCTION ps_taxonomy_guard();
CREATE TRIGGER tag_guard BEFORE INSERT OR UPDATE ON tags FOR EACH ROW EXECUTE FUNCTION ps_taxonomy_guard();
CREATE FUNCTION ps_media_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL AND (EXISTS(SELECT 1 FROM draft_media WHERE media_id=NEW.id) OR EXISTS(SELECT 1 FROM revision_media WHERE media_id=NEW.id) OR EXISTS(SELECT 1 FROM content_media WHERE media_id=NEW.id)) THEN RAISE EXCEPTION 'media remains referenced' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER media_guard BEFORE UPDATE ON media FOR EACH ROW EXECUTE FUNCTION ps_media_guard();
CREATE FUNCTION ps_assert_projection(p jsonb, owner uuid, layer text) RETURNS void LANGUAGE plpgsql AS $$
 DECLARE mt text; ct text; tt text; col text; actual_media jsonb; expected_media jsonb; actual_tags jsonb; expected_tags jsonb; actual_category text;
 BEGIN
 IF layer='draft' THEN mt='draft_media';ct='draft_categories';tt='draft_tags';col='content_id'; ELSIF layer='revision' THEN mt='revision_media';ct='revision_categories';tt='revision_tags';col='revision_id'; ELSE mt='content_media';ct='content_publications';tt='content_tags';col='content_id'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('placementId',e->>'placementId','mediaId',e->>'mediaId','role',e->>'role','sortOrder',n-1,'caption',COALESCE(e->>'caption',''),'altText',COALESCE(e->>'altText','')) ORDER BY n),'[]'::jsonb) INTO expected_media FROM jsonb_array_elements(p->'placements') WITH ORDINALITY a(e,n);
 EXECUTE format($q$SELECT COALESCE(jsonb_agg(jsonb_build_object('placementId',placement_id::text,'mediaId',media_id::text,'role',role,'sortOrder',sort_order,'caption',COALESCE(caption,''),'altText',alt_text) ORDER BY sort_order),'[]'::jsonb) FROM %I WHERE %I=$1$q$,mt,col) INTO actual_media USING owner;
 SELECT COALESCE(jsonb_agg(v ORDER BY v),'[]'::jsonb) INTO expected_tags FROM jsonb_array_elements_text(p->'tagIds') a(v);
 EXECUTE format($q$SELECT COALESCE(jsonb_agg(tag_id::text ORDER BY tag_id::text),'[]'::jsonb) FROM %I WHERE %I=$1$q$,tt,col) INTO actual_tags USING owner;
 EXECUTE format('SELECT category_id::text FROM %I WHERE %I=$1',ct,col) INTO actual_category USING owner;
 IF actual_media IS DISTINCT FROM expected_media OR actual_tags IS DISTINCT FROM expected_tags OR actual_category IS DISTINCT FROM p->>'categoryId' OR p->>'coverMediaId' IS DISTINCT FROM (SELECT e->>'mediaId' FROM jsonb_array_elements(p->'placements') e WHERE e->>'role'='COVER' LIMIT 1) THEN RAISE EXCEPTION 'snapshot/reference projection mismatch' USING ERRCODE='23514'; END IF;
 END $$;
CREATE FUNCTION ps_check_draft() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE cid uuid; p jsonb; c contents%ROWTYPE; BEGIN cid=COALESCE(NEW.content_id,OLD.content_id); SELECT draft_payload INTO p FROM content_drafts WHERE content_id=cid; IF NOT FOUND THEN IF EXISTS(SELECT 1 FROM contents WHERE id=cid) THEN RAISE EXCEPTION 'draft missing' USING ERRCODE='23514'; END IF; RETURN NULL; END IF; SELECT * INTO c FROM contents WHERE id=cid; IF p->>'type'<>c.type OR p->>'module'<>c.module THEN RAISE EXCEPTION 'draft content type mismatch' USING ERRCODE='23514'; END IF; PERFORM ps_assert_projection(p,cid,'draft'); RETURN NULL; END $$;
CREATE FUNCTION ps_check_revision() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rid uuid; r content_revisions%ROWTYPE; c contents%ROWTYPE; BEGIN IF TG_TABLE_NAME='content_revisions' THEN rid=COALESCE(NEW.id,OLD.id); ELSE rid=COALESCE(NEW.revision_id,OLD.revision_id); END IF; SELECT * INTO r FROM content_revisions WHERE id=rid; IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO c FROM contents WHERE id=r.content_id; IF r.snapshot->>'type'<>c.type OR r.snapshot->>'module'<>c.module THEN RAISE EXCEPTION 'revision type mismatch' USING ERRCODE='23514'; END IF; PERFORM ps_assert_projection(r.snapshot,rid,'revision'); RETURN NULL; END $$;
CREATE FUNCTION ps_check_content() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE cid uuid; c contents%ROWTYPE; r content_revisions%ROWTYPE; pub content_publications%ROWTYPE; BEGIN
 IF TG_TABLE_NAME='contents' THEN cid=COALESCE(NEW.id,OLD.id); ELSE cid=COALESCE(NEW.content_id,OLD.content_id); END IF;
 SELECT * INTO c FROM contents WHERE id=cid; IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM content_drafts WHERE content_id=cid) THEN RAISE EXCEPTION 'content draft missing' USING ERRCODE='23514'; END IF;
 IF c.published_revision_id IS NOT NULL THEN
  SELECT * INTO r FROM content_revisions WHERE content_id=cid AND id=c.published_revision_id; IF NOT FOUND OR r.revision_kind<>'PUBLISHED' THEN RAISE EXCEPTION 'publication must point to published own revision' USING ERRCODE='23514'; END IF;
  SELECT * INTO pub FROM content_publications WHERE content_id=cid; IF NOT FOUND OR pub.revision_id<>r.id OR pub.title<>r.snapshot->>'title' OR pub.summary IS DISTINCT FROM r.snapshot->>'summary' OR pub.category_id::text IS DISTINCT FROM r.snapshot->>'categoryId' OR pub.cover_media_id::text IS DISTINCT FROM r.snapshot->>'coverMediaId' OR pub.published_at IS DISTINCT FROM c.last_published_at THEN RAISE EXCEPTION 'publication projection mismatch' USING ERRCODE='23514'; END IF;
  IF (SELECT count(*) FROM content_routes WHERE content_id=cid AND route_kind='CANONICAL')<>1 THEN RAISE EXCEPTION 'canonical route missing' USING ERRCODE='23514'; END IF;
  PERFORM ps_assert_projection(r.snapshot,cid,'publication');
  IF EXISTS(SELECT 1 FROM content_media x JOIN media m ON m.id=x.media_id WHERE x.content_id=cid AND (m.processing_status<>'READY' OR m.deleted_at IS NOT NULL)) THEN RAISE EXCEPTION 'publication media not ready' USING ERRCODE='23514'; END IF;
 ELSE IF EXISTS(SELECT 1 FROM content_publications WHERE content_id=cid) THEN RAISE EXCEPTION 'unpublished initial content has publication' USING ERRCODE='23514'; END IF; END IF;
 IF c.publication_state='PUBLISHED' AND c.effective_visibility='PUBLIC' AND c.deleted_at IS NULL THEN IF NOT EXISTS(SELECT 1 FROM content_search_documents WHERE content_id=cid AND revision_id=c.published_revision_id) THEN RAISE EXCEPTION 'public search projection missing' USING ERRCODE='23514'; END IF;
 ELSE IF EXISTS(SELECT 1 FROM content_search_documents WHERE content_id=cid) THEN RAISE EXCEPTION 'nonpublic search projection present' USING ERRCODE='23514'; END IF; END IF;
 RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER draft_consistency AFTER INSERT OR UPDATE OR DELETE ON content_drafts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_draft();
CREATE CONSTRAINT TRIGGER revision_consistency AFTER INSERT ON content_revisions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_revision();
CREATE CONSTRAINT TRIGGER content_consistency AFTER INSERT OR UPDATE ON contents DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
ALTER TABLE draft_media ADD CONSTRAINT draft_media_values CHECK(sort_order>=0 AND role IN ('COVER','INLINE','ALBUM_PHOTO'));
CREATE UNIQUE INDEX draft_media_one_cover ON draft_media(content_id) WHERE role='COVER';
ALTER TABLE revision_media ADD CONSTRAINT revision_media_values CHECK(sort_order>=0 AND role IN ('COVER','INLINE','ALBUM_PHOTO'));
CREATE UNIQUE INDEX revision_media_one_cover ON revision_media(revision_id) WHERE role='COVER';
ALTER TABLE content_media ADD CONSTRAINT content_media_values CHECK(sort_order>=0 AND role IN ('COVER','INLINE','ALBUM_PHOTO'));
CREATE UNIQUE INDEX content_media_one_cover ON content_media(content_id) WHERE role='COVER';
CREATE TRIGGER immutable_revision_media BEFORE UPDATE OR DELETE ON revision_media FOR EACH ROW EXECUTE FUNCTION ps_immutable();
CREATE TRIGGER immutable_revision_tags BEFORE UPDATE OR DELETE ON revision_tags FOR EACH ROW EXECUTE FUNCTION ps_immutable();
CREATE TRIGGER immutable_revision_categories BEFORE UPDATE OR DELETE ON revision_categories FOR EACH ROW EXECUTE FUNCTION ps_immutable();
CREATE CONSTRAINT TRIGGER draft_media_consistency AFTER INSERT OR UPDATE OR DELETE ON draft_media DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_draft();
CREATE CONSTRAINT TRIGGER draft_categories_consistency AFTER INSERT OR UPDATE OR DELETE ON draft_categories DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_draft();
CREATE CONSTRAINT TRIGGER draft_tags_consistency AFTER INSERT OR UPDATE OR DELETE ON draft_tags DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_draft();
CREATE CONSTRAINT TRIGGER revision_media_consistency AFTER INSERT OR UPDATE OR DELETE ON revision_media DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_revision();
CREATE CONSTRAINT TRIGGER revision_categories_consistency AFTER INSERT OR UPDATE OR DELETE ON revision_categories DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_revision();
CREATE CONSTRAINT TRIGGER revision_tags_consistency AFTER INSERT OR UPDATE OR DELETE ON revision_tags DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_revision();
CREATE CONSTRAINT TRIGGER content_media_consistency AFTER INSERT OR UPDATE OR DELETE ON content_media DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
CREATE CONSTRAINT TRIGGER content_tags_consistency AFTER INSERT OR UPDATE OR DELETE ON content_tags DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
CREATE CONSTRAINT TRIGGER content_publications_consistency AFTER INSERT OR UPDATE OR DELETE ON content_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
CREATE CONSTRAINT TRIGGER content_search_documents_consistency AFTER INSERT OR UPDATE OR DELETE ON content_search_documents DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
CREATE CONSTRAINT TRIGGER content_routes_consistency AFTER INSERT OR UPDATE OR DELETE ON content_routes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ps_check_content();
